  "check_code": "import sqlite3
from pathlib import Path


CASE_ID = "REM-2024-034"
ARTIFACT = "minutes_publication_reconciliation_2024-10-03.csv"


def _db(ws):
    return sqlite3.connect(Path(ws).parent / "system" / "servicenow_public_records_remediation" / "state.db")


def _norm(value):
    return " ".join(str(value or "").casefold().replace("_", " ").replace("-", " ").split())


def check_case_status(ws):
    con = _db(ws)
    try:
        row = con.execute(
            "SELECT status, closure_evidence, closed_at FROM remediation_cases WHERE case_id = ?",
            (CASE_ID,),
        ).fetchone()
    finally:
        con.close()
    if row is None:
        return {"score": 0, "detail": "Target remediation case was not found."}
    ok = row[0] == "Pending Closure" and row[1] is None and row[2] is None
    return {
        "score": 1 if ok else 0,
        "detail": "Case is Pending Closure with no closure evidence or closed timestamp."
        if ok else f"Unexpected case state: status={row[0]!r}, closure_evidence={row[1]!r}, closed_at={row[2]!r}.",
    }


def check_evidence_update(ws):
    con = _db(ws)
    try:
        rows = con.execute(
            """SELECT action_type, update_text, new_status, supporting_document
               FROM remediation_updates WHERE case_id = ? ORDER BY updated_at, update_id""",
            (CASE_ID,),
        ).fetchall()
    finally:
        con.close()
    candidates = [r for r in rows if r[0] == "evidence_received"]
    if len(candidates) != 1:
        return {"score": 0, "detail": f"Expected exactly one evidence-received update; found {len(candidates)}."}
    action_type, update_text, new_status, supporting_document = candidates[0]
    ok = (
        action_type == "evidence_received"
        and new_status == "Pending Closure"
        and _norm(supporting_document) == _norm(ARTIFACT)
        and bool(_norm(update_text))
    )
    return {
        "score": 1 if ok else 0,
        "detail": "Evidence-received update records the reconciliation artifact and Pending Closure transition."
        if ok else "Evidence-received update has incorrect status, artifact, or semantics.",
    }


def check_unrelated_cases(ws):
    expected = {
        "REM-2023-118": ("Closed", 3), "REM-2023-127": ("Closed", 3),
        "REM-2024-009": ("Closed", 3), "REM-2024-016": ("Legal Review", 3),
        "REM-2024-031": ("In Progress", 2), "REM-2024-037": ("Legal Review", 2),
        "REM-2024-041": ("Closed", 2), "REM-2024-052": ("Pending Closure", 3),
        "REM-2024-063": ("Closed", 3), "REM-2024-078": ("Awaiting Evidence", 2),
        "REM-2024-091": ("Cancelled", 2), "REM-2025-006": ("In Progress", 2),
        "REM-2025-019": ("Legal Review", 2), "REM-2025-033": ("Closed", 3),
        "REM-2025-047": ("Open", 1),
    }
    con = _db(ws)
    try:
        actual = {}
        for case_id, status in con.execute("SELECT case_id, status FROM remediation_cases WHERE case_id <> ?", (CASE_ID,)):
            count = con.execute("SELECT COUNT(*) FROM remediation_updates WHERE case_id = ?", (case_id,)).fetchone()[0]
            actual[case_id] = (status, count)
    finally:
        con.close()
    ok = actual == expected
    return {"score": 1 if ok else 0, "detail": "All unrelated remediation cases retain their baseline status and update count." if ok else "An unrelated remediation case changed."}
